package com.leetcode.backend.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="assessment_creator_applications",indexes={@Index(name="idx_creator_application_user",columnList="user_id,status"),@Index(name="idx_creator_application_status",columnList="status,submitted_at")})
public class AssessmentCreatorApplication {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false,length=120) private String fullName; @Column(nullable=false,length=160) private String organization; @Column(nullable=false,length=120) private String roleTitle; @Column(nullable=false,length=160) private String purpose; @Column(length=300) private String website; @Column(length=150) private String organizationEmail; @Column(nullable=false,columnDefinition="TEXT") private String intendedUse; @Column(nullable=false,length=80) private String country; @Column(nullable=false,length=60) private String documentType; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private AssessmentEnums.CreatorStatus status=AssessmentEnums.CreatorStatus.EMAIL_OTP_PENDING; @Column(name="otp_hash",length=100) private String otpHash; @Column(name="otp_expires_at") private LocalDateTime otpExpiresAt; @Column(name="otp_attempts",nullable=false) private int otpAttempts; @Column(name="otp_last_sent_at") private LocalDateTime otpLastSentAt; @Column(name="submitted_at") private LocalDateTime submittedAt; @Column(name="decided_at") private LocalDateTime decidedAt; @Column(name="decision_reason",length=500) private String decisionReason; @Column(name="created_at",nullable=false) private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();}
 public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getOrganization(){return organization;} public void setOrganization(String v){organization=v;} public String getRoleTitle(){return roleTitle;} public void setRoleTitle(String v){roleTitle=v;} public String getPurpose(){return purpose;} public void setPurpose(String v){purpose=v;} public String getWebsite(){return website;} public void setWebsite(String v){website=v;} public String getOrganizationEmail(){return organizationEmail;} public void setOrganizationEmail(String v){organizationEmail=v;} public String getIntendedUse(){return intendedUse;} public void setIntendedUse(String v){intendedUse=v;} public String getCountry(){return country;} public void setCountry(String v){country=v;} public String getDocumentType(){return documentType;} public void setDocumentType(String v){documentType=v;} public AssessmentEnums.CreatorStatus getStatus(){return status;} public void setStatus(AssessmentEnums.CreatorStatus v){status=v;} public String getOtpHash(){return otpHash;} public void setOtpHash(String v){otpHash=v;} public LocalDateTime getOtpExpiresAt(){return otpExpiresAt;} public void setOtpExpiresAt(LocalDateTime v){otpExpiresAt=v;} public int getOtpAttempts(){return otpAttempts;} public void setOtpAttempts(int v){otpAttempts=v;} public LocalDateTime getOtpLastSentAt(){return otpLastSentAt;} public void setOtpLastSentAt(LocalDateTime v){otpLastSentAt=v;} public LocalDateTime getSubmittedAt(){return submittedAt;} public void setSubmittedAt(LocalDateTime v){submittedAt=v;} public LocalDateTime getDecidedAt(){return decidedAt;} public void setDecidedAt(LocalDateTime v){decidedAt=v;} public String getDecisionReason(){return decisionReason;} public void setDecisionReason(String v){decisionReason=v;}
}
